begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(16);
insert into auth.users(id,email) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test');
insert into public.app_users(id,email,full_name) values('99300000-0000-4000-8000-000000000001','tax-preparer@example.test','Tax preparer'),('99300000-0000-4000-8000-000000000002','tax-reviewer@example.test','Tax reviewer');
insert into public.orgs(id,name,slug) values('99300000-0000-4000-8000-000000000003','Tax workpaper acceptance','tax-workpaper-acceptance');
insert into public.roles(id,key,label,scope) values('99300000-0000-4000-8000-000000000004','tax_workpaper_acceptance','Tax acceptance','org');
insert into public.memberships(org_id,user_id,role_id) values('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','99300000-0000-4000-8000-000000000004'),('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000002','99300000-0000-4000-8000-000000000004');
create function pg_temp.tax_base() returns jsonb language sql as $$select jsonb_build_object('basis','cash','version',1,'start_date','2026-01-01','end_date','2026-12-31','net_income_cents',0,'source_revision',public.books_tax_source_revision(public.capture_books_export_snapshot('99300000-0000-4000-8000-000000000003'),'2026-12-31'))$$;
create temporary table confirmation_ids(name text primary key,id uuid);
create function pg_temp.confirmation_prepare(key text,note text default 'Reviewed all tax differences using accountant workpaper TAX-2026; no adjustments required.',supersedes uuid default null) returns uuid language sql as $$select public.prepare_books_tax_workpaper('99300000-0000-4000-8000-000000000003','99300000-0000-4000-8000-000000000001','2026-01-01','2026-12-31',repeat('a',64),pg_temp.tax_base(),'[]',key,supersedes,note)$$;
select ok(not has_function_privilege('authenticated','public.withdraw_books_tax_workpaper(uuid,uuid,uuid,text)','execute') and not has_function_privilege('anon','public.prepare_books_tax_workpaper(uuid,uuid,date,date,text,jsonb,jsonb,text,uuid,text)','execute'),'browser roles cannot withdraw or prepare confirmations');
select throws_like($$select pg_temp.confirmation_prepare('tax-confirmation-no-notes','')$$,'%confirmation_check%','empty adjustments require substantive evidence');
select lives_ok($$insert into confirmation_ids values('confirmation',pg_temp.confirmation_prepare('tax-confirmation-review-key'))$$,'explicit no-adjustment confirmation prepared');
select is(jsonb_array_length((select lines from public.books_tax_adjustment_workpapers where id=(select id from confirmation_ids where name='confirmation'))),0,'no artificial zero-value line is posted');
select is(pg_temp.confirmation_prepare('tax-confirmation-review-key'),(select id from confirmation_ids where name='confirmation'),'same evidence preparation is idempotent');
select throws_like($$select pg_temp.confirmation_prepare('tax-confirmation-review-key','Different no-adjustment reasoning')$$,'%different evidence%','retry cannot rewrite no-adjustment rationale');
select throws_like($$update public.books_tax_adjustment_workpapers set preparation_notes='Changed preparation evidence' where id=(select id from confirmation_ids where name='confirmation')$$,'%immutable%','confirmation rationale is immutable');
set local role service_role;
select lives_ok($$select public.review_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-confirmation-review-key'),'99300000-0000-4000-8000-000000000002',repeat('a',64),'Reviewed TAX-2026 calculation and no differences remain')$$,'service-role separate reviewer approves confirmation');
select throws_like($$select public.withdraw_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-confirmation-review-key'),'99300000-0000-4000-8000-000000000001','Draft withdrawn after review')$$,'%Only draft%','approved confirmation cannot be withdrawn');
reset role;
select lives_ok($$insert into confirmation_ids values('withdraw',pg_temp.confirmation_prepare('tax-confirmation-withdraw-key','Reviewed TAX-2026; replacement requires no adjustments.',(select id from confirmation_ids where name='confirmation')))$$,'second draft prepared');
select throws_like($$select public.withdraw_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from confirmation_ids where name='withdraw'),'99300000-0000-4000-8000-000000000001','ok')$$,'%Substantive%','withdrawal requires reason');
select throws_like($$select public.withdraw_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from confirmation_ids where name='withdraw'),'99300000-0000-4000-8000-000000000099','Incorrect draft withdrawn')$$,'%active organization actor%','foreign actor cannot withdraw');
set local role service_role;
select lives_ok($$select public.withdraw_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-confirmation-withdraw-key'),'99300000-0000-4000-8000-000000000001','Duplicate draft entered in error')$$,'service-role withdrawal preserves history');
select is(public.withdraw_books_tax_workpaper('99300000-0000-4000-8000-000000000003',(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-confirmation-withdraw-key'),'99300000-0000-4000-8000-000000000001','Duplicate draft entered in error'),(select id from public.books_tax_adjustment_workpapers where idempotency_key='tax-confirmation-withdraw-key'),'withdrawal retry is idempotent');
reset role;
select ok((select status='withdrawn' and preparation_notes='Reviewed TAX-2026; replacement requires no adjustments.' and closed_by=prepared_by and closed_at is not null and close_reason='Duplicate draft entered in error' from public.books_tax_adjustment_workpapers where id=(select id from confirmation_ids where name='withdraw')),'withdrawal retains preparation evidence and closure identity');
select is((select status from public.books_tax_adjustment_workpapers where id=(select id from confirmation_ids where name='confirmation')),'approved','withdrawing replacement preserves original approval');
select * from finish();
rollback;
